// What an agent is told it may call over MCP: each tool's name, what it
// answers and the arguments it takes. tools.rs answers the calls.

use serde_json::{json, Value};

use super::tools::schema;

// Exposed surface == the vault's own declared programmatic-safe boundary.
pub(super) fn tools() -> Value {
    json!([
        {"name": "skarbiec_health",
         "description": "Liveness probe for the skarbiec vault. Returns {ok, service}. No credentials touched.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_list",
         "description": "List credential item metadata (ids, type, revision counts, tags). Never returns secret values.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_route_resolve",
         "description": "Resolve one declared route the sanctioned way: policy- and token-gated; emits an owner-only env file and returns only its path plus the exported variable NAMES (ADMIN_EMAIL/ADMIN_PASSWORD/ADMIN_TOTP). Values are never returned. The server must be configured with SKARBIEC_MCP_CONSUMER, SKARBIEC_MCP_TOKEN (or SKARBIEC_MCP_TOKEN_FILE), and an absolute SKARBIEC_MCP_OUT_DIR; the token is never a tool argument.",
         "inputSchema": schema(json!({"name": {"type": "string", "description": "The resource name to resolve, as route resolve accepts it: login:<item> for one login item, provider:<provider>, agent:<agent>, or a hand-declared resource."}}), vec!["name"])},
        {"name": "skarbiec_audit",
         "description": "Return the tamper-evident audit journal (at/op/extra/prev/hash chain). Only operation names and non-sensitive identifiers are journalled; never values.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_history",
         "description": "List every saved version of one item (stamp, revision, kind, writer) without decrypting anything. Never returns secret values.",
         "inputSchema": schema(json!({"id": {"type": "string", "description": "The item id."}}), vec!["id"])},
        {"name": "skarbiec_tags",
         "description": "List the registered tag namespaces and every tag the live items carry, with the items carrying each and whether a namespace covers it.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_grants_reaching",
         "description": "List the consumers whose grant reaches one item, directly or through a role tag it carries, with the capabilities that do. Never returns a bearer or public key.",
         "inputSchema": schema(json!({"id": {"type": "string", "description": "The item id."}}), vec!["id"])},
        {"name": "skarbiec_certificates",
         "description": "List every live certificate item's subject, issuer and end of validity, soonest first, and the ones whose certificate could not be read. Never returns a private key.",
         "inputSchema": schema(json!({"expiring_before": {"type": "string", "description": "Optional UTC time (YYYY-MM-DDTHH:MM:SSZ); keeps the certificates ending before it."}}), vec![])},
        {"name": "skarbiec_recipient_items",
         "description": "List every live and trashed item one registered recipient can open, read from the item envelopes without decrypting anything.",
         "inputSchema": schema(json!({"uid": {"type": "string", "description": "The recipient uid."}}), vec!["uid"])},
        {"name": "skarbiec_duplicates",
         "description": "List groups of live items holding exactly the same payload, compared by the fingerprints in their envelopes. Never returns a value or a fingerprint.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_find",
         "description": "Find live items whose name, username, email, phone, API user, client id or site — and with notes true, notes — contains a text, naming where each matched. Never compares or returns a secret, and never returns the matching value.",
         "inputSchema": schema(json!({
             "text": {"type": "string", "description": "The text to look for, regardless of case."},
             "notes": {"type": "boolean", "description": "Also look in each item's notes."}
         }), vec!["text"])},
        {"name": "skarbiec_shares",
         "description": "List every share given with an end (share --until), soonest first, with whether it has ended. Changes nothing; never returns a value.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_unused",
         "description": "Name what nobody has used since a moment, from the audit journal: the grants whose consumer no entry names (grants) and the live items no entry names (items). Changes nothing; never returns a value or a bearer.",
         "inputSchema": schema(json!({"since": {"type": "string", "description": "A UTC time of the vault's stamp form."}}), vec!["since"])},
        {"name": "skarbiec_expiry",
         "description": "List the items whose recorded expiry (expiry set) falls first, soonest first, or only before a moment, each with whether it has passed. Opens no item; changes nothing.",
         "inputSchema": schema(json!({"before": {"type": "string", "description": "Optional: a UTC time of the vault's stamp form."}}), vec![])},
        {"name": "skarbiec_password_age",
         "description": "List every live login with when its password was last set, oldest first, or only the ones set before a moment; a saved version that would not open is named with its error. Only moments are returned, never a value; changes nothing.",
         "inputSchema": schema(json!({"set_before": {"type": "string", "description": "Optional: a UTC time of the vault's stamp form."}}), vec![])},
        {"name": "skarbiec_logins_for",
         "description": "Name the logins autofill offers on one site — each with its name, username and sites — the logins offered on no site, and any that would not open. Answers which login to use for a site; never returns a password or a code, and changes nothing.",
         "inputSchema": schema(json!({"site": {"type": "string", "description": "A host such as github.com, or a whole address."}}), vec!["site"])},
        {"name": "skarbiec_audit_summary",
         "description": "Count the audit journal over a span: how often each operation ran, which consumers acted and which items were named, most frequent first. Names only what journal entries name; changes nothing.",
         "inputSchema": schema(json!({"since": {"type": "string", "description": "A UTC time of the vault's stamp form."}, "until": {"type": "string", "description": "Optional: a UTC time of the vault's stamp form."}}), vec!["since"])},
        {"name": "skarbiec_review",
         "description": "Run one security review held to a moment: secret health, certificates, keys and recorded expiries ending before it, stale and unused items and grants, passwords set before it, logins offered nowhere, due rotations and more, each section with its own answer or error. With breached, secret health also asks Have I Been Pwned's k-anonymous range API. Names item ids only, never a value; it appends a review journal record.",
         "inputSchema": schema(json!({"before": {"type": "string", "description": "A UTC time of the vault's stamp form."}, "breached": {"type": "boolean", "description": "Optional: also ask Have I Been Pwned."}}), vec!["before"])},
        {"name": "skarbiec_pins",
         "description": "List the pinned items, the ones the owner keeps at the front, in the order they were pinned, each with whether it is still live. Opens no item; changes nothing.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_codes_missing",
         "description": "Name the live logins whose site offers authenticator codes, as the 2FA Directory lists them, that keep no seed, each with the site's setup page. Downloads only the directory's list of sites; never returns a password or a seed, and changes nothing.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_site_breaches",
         "description": "Name the live logins whose site Have I Been Pwned lists as breached after their password was set — the passwords to change first — and apart those changed since, each with the breach, its day and when the password was set. Downloads only the public list of breaches; never returns a password, and changes nothing.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_password_rules",
         "description": "Read the password rules one login keeps for its site, in the Password Rules language, with the generator options they ask for, so a value generated for the site is one it accepts. Never returns a password; changes nothing.",
         "inputSchema": schema(json!({"id": {"type": "string", "description": "The login's item id."}}), vec!["id"])},
        {"name": "skarbiec_scan",
         "description": "Find the files under a path on this machine that hold a vault value in plain text — a .env, a config file, a shell history — naming each copy's file, line, item and field, so it can be deleted before it is committed or shared. Never returns a value; changes nothing.",
         "inputSchema": schema(json!({"path": {"type": "string", "description": "A file or directory; symbolic links are not followed."}, "fields": {"type": "string", "description": "The fields whose values are looked for, comma separated, such as password,token,api_key."}, "min_length": {"type": "string", "description": "Optional: values shorter than this are not compared."}}), vec!["path", "fields"])},
        {"name": "skarbiec_token_expiry",
         "description": "List every JSON Web Token a live item holds with its issuer and when it was issued and runs out, soonest end first, or only those ending before a moment, so an expired stored token is replaced before a program fails on it. Never returns a token or another claim; changes nothing.",
         "inputSchema": schema(json!({"before": {"type": "string", "description": "Optional: a UTC time of the vault's stamp form; only tokens ending before it."}}), vec![])},
        {"name": "skarbiec_exposure",
         "description": "Answer, for one item, everything that could have learned its value: the keys it opens with, the consumers whose grant reaches it, and the consumers the journal names acting on it, optionally since a moment, with the steps that shut each out. Never returns a value; changes nothing but appending the exposure journal record.",
         "inputSchema": schema(json!({"id": {"type": "string", "description": "The item's id."}, "since": {"type": "string", "description": "Optional: a UTC time of the vault's stamp form; only journal entries from it."}}), vec!["id"])},
        {"name": "skarbiec_rotations",
         "description": "List every rotation policy — the item, how many days apart, what rotates it (a Weles provider and consumer, or the provider `skarbiec rotate --with` rotates through — database, aws, gcp, azure, gitlab, cloudflare, twilio, sendgrid, vercel or ssh — with its flags), when it is next due, whether it is due now and why, and how the last attempt went in the rotator's own words — or with due only the ones the next rotation run starts, and whether this vault runs them at all. Starts no rotation; never returns a value.",
         "inputSchema": schema(json!({"due": {"type": "boolean", "description": "Optional: only the policies due now."}}), vec![])},
        {"name": "skarbiec_credential_helpers",
         "description": "Say which tools on this machine read their credentials from the vault — git, Docker, the AWS CLI, kubectl, Terraform and Cargo through `skarbiec helper`, npm, twine, the GitHub CLI, gem, Hugging Face, flyctl and the Vercel CLI through `skarbiec tool` — whether each program they run is still there, and which sign-ins are still kept in plain text beside them (~/.git-credentials, Docker's auths, credentials.tfrc.json, credentials.toml, .npmrc, ~/.pypirc, gh's hosts.yml, gem's credentials, Hugging Face's token and stored_tokens, ~/.fly/config.yml, the Vercel CLI's auth.json), with the command that moves each into the vault. Names files, hosts and registries; never returns a token, and changes nothing.",
         "inputSchema": schema(json!({}), vec![])},
        {"name": "skarbiec_bindings_check",
         "description": "Check a bindings file exec --env-from reads, on the server's machine: for every NAME=<id>:<field> line, whether the program would get a value or why not — the item is in the trash, no item has that id, it holds no such field or an empty one, or it would not open. Never returns a value; appends only the bindings-checked journal record.",
         "inputSchema": schema(json!({"file": {"type": "string", "description": "The bindings file's absolute path."}}), vec!["file"])},
    ])
}
